head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > applyAllColumnStyle]<br/>Column 의 style 속성에 설정한 값을 모두 적용할지 설정합니다.",
    "validation" : [
        "true 설정 시 Column 의 style 속성에 설정한 값을 모두 적용합니다.",
        "false(기본값) 설정 시 Column 의 style 속성에 설정한 값 중 첫번째 설정값만 적용합니다.",
        "미설정 시 기본값 false 로 동작합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // applyAllColumnStyle 옵션 정보 라벨 생성
    $c.gcm.createLabel('label="Column0: background-color:lightblue;color:red;font-weight:bold;"', '', 'label1');
    $c.gcm.createLabel('label="Column1: background-color:lightyellow;color:blue;font-style:italic;"', '', 'label2');
    $c.gcm.createLabel('label="Column2: background-color:lightgreen;color:purple;text-decoration:underline;"', '', 'label3');
    $c.gcm.createLabel('label="Column3: background-color:lightpink;color:darkgreen;font-weight:bold;"', '', 'label4');

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 조건 설정 - applyAllColumnStyle
    let applyAllColumnStyleText = con_applyAllColumnStyle.getText();

    // target 생성 (column 별로 다중 style 적용한 custom gridView)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    let applyAttr = applyAllColumnStyleText === '' ? '' : 'applyAllColumnStyle="' + applyAllColumnStyleText + '" ';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + applyAttr + 'dataList="data:dlt_bind" checkAllType="false" id="" style="width:600px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="background-color:lightblue;color:red;font-weight:bold;" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="background-color:lightyellow;color:blue;font-style:italic;" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="background-color:lightgreen;color:purple;text-decoration:underline;" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="background-color:lightpink;color:darkgreen;font-weight:bold;" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_checkColumnStyle_onclick = function () {
    // Column 별로 정의한 style 속성 목록 (정의 순서 그대로)
    let definedStyles = [
        ["background-color", "color", "font-weight"],
        ["background-color", "color", "font-style"],
        ["background-color", "color", "text-decoration"],
        ["background-color", "color", "font-weight"]
    ];

    wf_body_bottom.getObj("scwin").setReturnValue("applyAllColumnStyle : " + target1.options.applyAllColumnStyle);

    for (let colIdx = 0; colIdx < 4; colIdx++) {
        let cellEl = document.querySelector("td[id*='target1_cell_0_" + colIdx + "']");
        if (cellEl) {
            let styleNames = definedStyles[colIdx];
            let parts = [];
            for (let i = 0; i < styleNames.length; i++) {
                let name = styleNames[i];
                let value = cellEl.style.getPropertyValue(name);
                parts.push(name + "=" + (value || "(미적용)"));
            }
            wf_body_bottom.getObj("scwin").setReturnValue("Cell(0, " + colIdx + ") → " + parts.join(", "));
        }
    }
}
